class PreviewReport:
    name: str
    category: str

    def __init__(self, name: str, category: str) -> None:
        self.name = name
        self.category = category

from rules import category
from models import PreviewReport

def build_reports(raw: str) -> list[PreviewReport]:
    reports: list[PreviewReport] = []
    for part in raw.split(","):
        name = part.strip().lower()
        if name:
            reports.append(PreviewReport(name, category(name)))
    return reports

def main() -> None:
    reports = build_reports(input())
    for item in reports:
        print(f"{item.category}:{item.name}")
    print(f"total={len(reports)}")

if __name__ == "__main__":
    main()

import unittest
from main import build_reports

class PreviewTests(unittest.TestCase):
    def test_cleaning_and_order(self):
        reports = build_reports(" A.TXT, ,b.csv,A.TXT ")
        self.assertEqual([(r.category, r.name) for r in reports],
                         [("text", "a.txt"), ("data", "b.csv"), ("text", "a.txt")])

    def test_empty(self):
        self.assertEqual(build_reports(" , "), [])

